def mst_edges(comps):
 edges=[]
 for i in range(len(comps)):
  for j in range(i+1,len(comps)):
   best=min((abs(a[0]-b[0])+abs(a[1]-b[1]),a,b) for a in comps[i] for b in comps[j])
   edges.append((best[0],i,j,best[1],best[2]))
 edges.sort()
 parent=list(range(len(comps)))
 def find(x):
  while parent[x]!=x: parent[x]=parent[parent[x]];x=parent[x]
  return x
 chosen=[]
 for d,i,j,a,b in edges:
  x,y=find(i),find(j)
  if x!=y:parent[x]=y;chosen.append((d,i,j,a,b))
 return chosen,edges
